CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL DEFAULT 'Nueva conversación', messages jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.conversations TO authenticated;
GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversations_owner ON public.conversations FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE INDEX conversations_user_idx ON public.conversations(user_id, updated_at DESC);
CREATE TABLE public.analysis_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, filename text NOT NULL, agent_slug text NOT NULL DEFAULT 'arqueologo', status text NOT NULL DEFAULT 'running', report text, error text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.analysis_runs TO authenticated;
GRANT ALL ON public.analysis_runs TO service_role;
ALTER TABLE public.analysis_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY analysis_owner_read ON public.analysis_runs FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE INDEX analysis_user_idx ON public.analysis_runs(user_id, created_at DESC);
CREATE TABLE public.trial_claims (user_id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES public.analysis_runs(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trial_claims TO authenticated;
GRANT ALL ON public.trial_claims TO service_role;
ALTER TABLE public.trial_claims ENABLE ROW LEVEL SECURITY;
CREATE POLICY trial_owner_read ON public.trial_claims FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.claim_free_analysis(p_filename text, p_agent_slug text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE r uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión para analizar'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); IF EXISTS (SELECT 1 FROM public.trial_claims WHERE user_id = auth.uid()) THEN RAISE EXCEPTION 'Tu prueba gratuita ya se ha utilizado. Solicita una suscripción mensual, trimestral o anual.'; END IF; INSERT INTO public.analysis_runs(user_id, filename, agent_slug) VALUES(auth.uid(), left(p_filename,200), left(p_agent_slug,100)) RETURNING id INTO r; INSERT INTO public.trial_claims(user_id,run_id) VALUES(auth.uid(),r); RETURN r; END $$;
REVOKE ALL ON FUNCTION public.claim_free_analysis(text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.claim_free_analysis(text,text) TO authenticated;
CREATE TABLE public.service_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, company text, role text, size text, message text, kind text NOT NULL, plan text, consent boolean NOT NULL DEFAULT false, marketing boolean NOT NULL DEFAULT false, policy_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.service_requests TO anon, authenticated;
GRANT ALL ON public.service_requests TO service_role;
ALTER TABLE public.service_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY submit_request ON public.service_requests FOR INSERT TO anon, authenticated WITH CHECK (consent = true AND length(email) < 320 AND length(message) < 10000);
CREATE TABLE public.ai_access_state (provider text PRIMARY KEY, blocked boolean NOT NULL DEFAULT false, reason text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ai_access_state TO service_role;
ALTER TABLE public.ai_access_state ENABLE ROW LEVEL SECURITY;